import{_ as n,o as a,c as i,a6 as t}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"TensorRT-LLM","description":"从 Bit 到 AGI · 第十一章：工程化（Serving） · NVIDIA 编译级 LLM 推理 TensorRT-LLM","frontmatter":{"title":"TensorRT-LLM","description":"从 Bit 到 AGI · 第十一章：工程化（Serving） · NVIDIA 编译级 LLM 推理 TensorRT-LLM","source":"https://daiw.org/manual/bit-to-agi/11-engineering/tensorrt-llm"},"headers":[],"relativePath":"manual/llm/bit-to-agi/11-engineering/tensorrt-llm.md","filePath":"manual/llm/bit-to-agi/11-engineering/tensorrt-llm.md"}'),e={name:"manual/llm/bit-to-agi/11-engineering/tensorrt-llm.md"};function l(r,s,p,h,o,d){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="tensorrt-llm" tabindex="-1">TensorRT-LLM <a class="header-anchor" href="#tensorrt-llm" aria-label="Permalink to &quot;TensorRT-LLM&quot;">​</a></h1><blockquote><p>从 Bit 到 AGI · 第十一章：工程化（Serving） · NVIDIA 编译级 LLM 推理 TensorRT-LLM</p></blockquote><p>vLLM 和 SGLang 是「解释执行」：PyTorch 算子 + 运行时调度。当你把延迟压到极限、要在 <strong>H100 / H200 / B200 / L40S</strong> 上榨干 Tensor Core，就需要 <strong>编译</strong>——把模型图融合、量化、选最优 kernel，生成不可改但极快的 <strong>TensorRT Engine</strong>。TensorRT-LLM 是 NVIDIA 官方的这条路径。</p><h2 id="直觉" tabindex="-1">直觉 <a class="header-anchor" href="#直觉" aria-label="Permalink to &quot;直觉&quot;">​</a></h2><p>vLLM 像<strong>现场编排的爵士乐队</strong>——灵活，即兴改曲。TensorRT-LLM 像<strong>预录的 studio 母带</strong>——建 engine 时要花几小时，但播放（推理）时每个音符都经过声学工程师（编译器）优化。代价：换模型、改 seq len 上限、改 batch size 往往要 <strong>rebuild engine</strong>。</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  HF[HuggingFace 权重] --&gt; BUILD[trtllm-build]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  BUILD --&gt; ENGINE[.engine 文件]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ENGINE --&gt; TRT[trtllm-serve / Triton]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TRT --&gt; API[OpenAI API / gRPC]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p><strong>TensorRT-LLM</strong> = NVIDIA 的 LLM 推理 SDK，包含：</p><table tabindex="0"><thead><tr><th>模块</th><th>作用</th></tr></thead><tbody><tr><td>Model Definition</td><td>各架构（Llama、GPT、Mixtral…）的 TRT 算子实现</td></tr><tr><td>Builder</td><td>图优化、kernel 自动调优、量化（FP8/INT8/INT4 AWQ/GPTQ）</td></tr><tr><td>Runtime</td><td>In-flight batching、Paged KV、Multi-GPU（TP/PP）</td></tr><tr><td>Triton Backend</td><td>与 NVIDIA Triton Inference Server 集成</td></tr></tbody></table><p><strong>关键指标</strong>：在相同硬件上相对 vLLM 的 <strong>speedup</strong>（常见 <strong>1.3～2.5×</strong> tok/s），以及 <strong>engine build 时间</strong>（70B 可达数小时）。</p><h2 id="例子" tabindex="-1">例子 <a class="header-anchor" href="#例子" aria-label="Permalink to &quot;例子&quot;">​</a></h2><p><strong>例 1：Llama-3-8B，单 H100 80GB，FP8</strong></p><table tabindex="0"><thead><tr><th>引擎</th><th>并发 64，512 in / 128 out</th><th>tok/s</th><th>TTFT P50</th></tr></thead><tbody><tr><td>vLLM bf16</td><td>~3 200</td><td>~280 ms</td><td></td></tr><tr><td>TensorRT-LLM FP8</td><td>~5 100</td><td>~190 ms</td><td></td></tr><tr><td>TensorRT-LLM INT4 AWQ</td><td>~6 800</td><td>~210 ms</td><td></td></tr></tbody></table><p>FP8 在 H100 上利用 <strong>Transformer Engine</strong>，精度损失通常 &lt; 0.5% on MMLU（需自家 eval 验证）。</p><p><strong>例 2：构建与启动</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 转换 HF 权重并 build engine</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> convert_checkpoint.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --model_dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./Llama-3-8B-Instruct</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output_dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tllm_checkpoint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dtype</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> float16</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">trtllm-build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --checkpoint_dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tllm_checkpoint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output_dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./engines/llama3-8b-fp8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --gemm_plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> float16</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --max_batch_size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 128</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --max_input_len</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8192</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --max_seq_len</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9216</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --use_fp8_context_fmha</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 启动服务</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">trtllm-serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./engines/llama3-8b-fp8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8001</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p><strong>例 3：Llama-3-70B，4×H100 TP=4，INT4</strong></p><table tabindex="0"><thead><tr><th>指标</th><th>数值</th></tr></thead><tbody><tr><td>吞吐（并发 32）</td><td>~2 200 tok/s</td></tr><tr><td>TTFT P95（2K in）</td><td>~1.4 s</td></tr><tr><td>Engine 体积</td><td>~38 GB（4 卡各一份 shard）</td></tr><tr><td>Build 时间</td><td>~2.5 h（含 auto-tuning）</td></tr></tbody></table><h2 id="量化" tabindex="-1">量化 <a class="header-anchor" href="#量化" aria-label="Permalink to &quot;量化&quot;">​</a></h2><p><strong>Engine 参数锁定</strong>：<code>max_batch_size</code>、<code>max_input_len</code>、<code>max_seq_len</code> 在 build 时写死。运行时超出会 reject 或 truncate——生产必须按 <strong>P99 prompt 长度 + 20% headroom</strong> 设定。</p><p><strong>FP8 算力</strong>（H100 SXM）：</p><ul><li>bf16 峰值 ~990 TFLOPS（dense）</li><li>FP8 峰值 ~1 979 TFLOPS（with sparsity 更高）</li></ul><p>实际 LLM decode 受 <strong>内存带宽</strong> 限制（~3.35 TB/s HBM3），INT4/FP8 的主要收益是 <strong>权重更小 → 带宽压力下降 → 更高 batch</strong>。</p><p><strong>成本对比</strong>（同等 SLO，70B 对话）：</p><table tabindex="0"><thead><tr><th>方案</th><th>GPU 数</th><th>月成本（按需 $3/GPU-h）</th></tr></thead><tbody><tr><td>vLLM bf16 TP=4</td><td>4×A100</td><td>~$8 640</td></tr><tr><td>TRT-LLM INT4 TP=4</td><td>4×H100</td><td>~$10 300（但 QPS <strong>~1.8×</strong> → 等效 <strong>~$5 700</strong>/等效吞吐）</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>TensorRT-LLM 与 Triton 组合是 NVIDIA 企业客户的标准栈；云厂商托管（如 NIM）底层也是类似编译管线。</p></div><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ol><li><strong>「编译一次永久用」</strong>——CUDA / driver / TRT-LLM 版本升级常需 rebuild；CI 里应存 build 脚本而非只存 engine 二进制。</li><li><strong>「INT4 一定比 FP8 快」</strong>——极短输出、小 batch 时 dequant 开销可能抵消收益；用 benchmark 而非假设。</li><li><strong>「只能在 NVIDIA 上跑」</strong>——正确，且无 ROCm 移植；AMD 路线看 vLLM / SGLang。</li><li><strong>「比 vLLM 麻烦就不值得」</strong>——当单卡 tok/s 差 <strong>40%</strong> 就意味着少买 <strong>40% GPU</strong>；10 卡以上集群通常值得投入编译流水线。</li></ol><h2 id="生产-checklist" tabindex="-1">生产 Checklist <a class="header-anchor" href="#生产-checklist" aria-label="Permalink to &quot;生产 Checklist&quot;">​</a></h2><p>TensorRT-LLM 运维重心在 <strong>engine 生命周期</strong>：</p><ol><li><strong>Build 流水线</strong>：CI 存 <code>convert_checkpoint.py</code> 参数 + git SHA；engine 二进制放 object storage，按 <code>{model}-{quant}-{max_seq}-{commit}</code> 命名。</li><li><strong>参数 headroom</strong>：<code>max_input_len</code> = P99 prompt × <strong>1.2</strong>；<code>max_batch_size</code> 覆盖峰值并发 ÷ 每 engine 舒适 batch。</li><li><strong>A/B 与回滚</strong>：新 engine 先 shadow 100% 流量 24 h，对比 tok/s 与 output 一致性（logprob diff &lt; 1e-3）。</li><li><strong>驱动锁定</strong>：Node 镜像 pin NVIDIA driver + CUDA + TRT-LLM 三元组；升级任一需完整 regression build。</li><li><strong>多 region</strong>：engine <strong>不能跨架构</strong>（H100 vs A100）；每 region 独立 build，避免拉错 artifact。</li></ol><p><strong>Break-even 估算</strong>：团队 <strong>≥6 GPU</strong> 且需 <strong>+40% tok/s</strong> 时，投入 0.5 FTE 维护 build 流水线通常 <strong>3～6 月</strong> 回本。</p><h2 id="动手试一试" tabindex="-1">动手试一试 <a class="header-anchor" href="#动手试一试" aria-label="Permalink to &quot;动手试一试&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 用官方 benchmark（需已 build engine）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> benchmarks/cpp/benchmark</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --engine_dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./engines/llama3-8b-fp8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --batch_size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --input_output_len</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;512,128&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --warm_up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --num_runs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>记录 <code>total latency</code>、<code>seq throughput (tokens/sec)</code>，与 vLLM <code>benchmark_serving.py</code> 同 prompt 分布对比。若 TRT 在 batch=1 时优势低于 10%，说明 workload 偏 latency-sensitive 小请求，优先优化 MII/vLLM 调度而非换 TRT。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>TensorRT-LLM 用 <strong>编译 + FP8/INT4</strong> 换极致吞吐，H100 上 8B 可达 <strong>~5 000～6 800 tok/s</strong>，相对 vLLM 常见 <strong>1.3～2×</strong> 提升；代价是 build 慢、参数写死、NVIDIA 锁定。适合延迟敏感、规模够大、团队能维护编译 CI 的场景。</p><p>→ 下一篇：<a href="/Front2Full/manual/llm/bit-to-agi/11-engineering/deepspeed">DeepSpeed</a></p>`,38)])])}const c=n(e,[["render",l]]);export{g as __pageData,c as default};
